void copy_and_null_terminate(const char* src, size_t size) {
    if (size == 0 || size > 1024) return;
    char* dest = (char*)malloc(size + 1); // Allocate space for null terminator
    if (!dest) return;
    for (size_t i = 0; i < size; i++) { // Loop condition changed to < size
