// FUNCTION: read_user_file
void read_user_file(const char* filename) {
    char filepath[512];

    // Sanitize filename to prevent path traversal
    if (strstr(filename, "..") != NULL || filename[0] == '/') {
        printf("Invalid filename: %s\n", filename);
        return;
    }

    snprintf(filepath, sizeof(filepath), "/var/www/html/users/%s", filename);
    FILE* f = fopen(filepath, "r"); 
    if (f) {
        printf("Successfully opened %s\n", filepath);
        fclose(f);
    } else {
        printf("Failed to open %s\n", filepath);
    }
}

// FUNCTION: ping_host
void ping_host(const char* ip_address) {
    // Validate the IP address
    for (const char* p = ip_address; *p; p++) {
        if (!(*p >= '0' && *p <= '9') && *p != '.') {
            printf("Invalid IP address: %s\n", ip_address);
            return; // Early exit on invalid input
        }
    }

    char cmd[256];
    snprintf(cmd, sizeof(cmd), "ping -c 1 %s", ip_address);
    printf("Executing: %s\n", cmd);
    system(cmd); 
}

